module.render:
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const body = sections[0] ? sections[0].trim() : '';
const rate = parseFloat(args.rate);
const speaker = parseInt(args.speaker, 10);
const icon = String(args.icon) !== 'false';
// The speaker: engine, prompt, the server's options, VOICEVOX shaping (voice / lang / rate below).
let attrs = ' data-fallback="' + esc(args.fallback || 'auto') + '"';
['engine', 'prompt', 'extra', 'pitch', 'intonation', 'volume'].forEach((f) => {
  const v = args[f];
  if (v != null && String(v).trim() !== '') attrs += ' data-' + f + '="' + esc(String(v).trim()) + '"';
});
return '<span class="mdp-mod-speak mdp-interactive" role="button" tabindex="0" title="Speak"'
  + ' data-lang="' + esc(args.lang || 'en-US') + '"'
  + ' data-voice="' + esc(args.voice || '') + '"'
  + ' data-speaker="' + (isNaN(speaker) ? -1 : speaker) + '"'
  + ' data-rate="' + (isNaN(rate) ? '' : rate) + '"' + attrs
  + ' data-highlight="' + (String(args.highlight) === 'false' ? 'false' : 'true') + '">'
  + (icon ? '<span class="mdp-speak-mark" aria-hidden="true">&#9654;</span>' : '')
  + '<span class="mdp-speak-body">' + body + '</span></span>';

module.script:
export default {
  init(el, ctx) {
    const HL = 'mdp-speak';
    const canHL = String(el.dataset.highlight) !== 'false'
      && typeof window.Highlight === 'function' && window.CSS && CSS.highlights;
    const clearHL = function () { if (canHL) { try { CSS.highlights.delete(HL); } catch (e) { /* ignore */ } } };
    const highlightRange = function (root, start, end) {
      if (!canHL || end <= start) return;
      try {
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        let pos = 0, sNode = null, sOff = 0, eNode = null, eOff = 0, n;
        while ((n = walker.nextNode())) {
          const len = (n.textContent || '').length;
          if (!sNode && start < pos + len) { sNode = n; sOff = start - pos; }
          if (end <= pos + len) { eNode = n; eOff = end - pos; break; }
          pos += len;
        }
        if (!sNode || !eNode) return;
        const range = document.createRange();
        range.setStart(sNode, Math.max(0, sOff));
        range.setEnd(eNode, Math.max(0, eOff));
        CSS.highlights.set(HL, new Highlight(range));
      } catch (e) { /* ignore */ }
    };

    const mark = el.querySelector('.mdp-speak-mark');
    const bodyEl = el.querySelector('.mdp-speak-body');

    // Shared state across surfaces: { playing: boolean, prog: {ci,cl}|{f}|null }
    const paint = function (st) {
      st = st || ctx.getShared() || {};
      const on = !!st.playing;
      el.classList.toggle('mdp-speak-playing', on);
      if (mark) mark.innerHTML = on ? '&#9632;' : '&#9654;';
      // A fallback is told in the tooltip only (nothing on the slide changes).
      el.title = st.note ? 'Speak — ' + st.note : 'Speak';
      if (on && st.prog && bodyEl) {
        const full = bodyEl.textContent || '';
        const text = full.trim();
        const lead = (full.match(/^\s*/) || [''])[0].length;
        const p = st.prog;
        if (typeof p.ci === 'number') {
          let end = (typeof p.cl === 'number' && p.cl > 0) ? p.ci + p.cl : -1;
          if (end < 0) {
            const m = text.slice(p.ci).search(/[\s,.!?;:、。]/);
            end = m > 0 ? p.ci + m : text.length;
          }
          highlightRange(bodyEl, lead + p.ci, lead + Math.min(end, text.length));
        } else if (typeof p.f === 'number') {
          highlightRange(bodyEl, lead, lead + Math.round(text.length * p.f));
        }
      } else if (!on) {
        clearHL();
      }
    };
    ctx.onShared(paint);

    const toggle = function () {
      const st = ctx.getShared() || {};
      if (st.playing) ctx.sendAction('stop');
      else ctx.sendAction('speak');
    };
    // Listeners must be removed on cleanup: re-init runs on the SAME DOM, and
    // a leftover listener would toggle the new playback straight off.
    const onClick = function (ev) { ev.stopPropagation(); toggle(); };
    const onKeydown = function (ev) {
      if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); ev.stopPropagation(); toggle(); }
    };
    el.addEventListener('click', onClick);
    el.addEventListener('keydown', onKeydown);
    ctx.onCleanup(function () {
      el.removeEventListener('click', onClick);
      el.removeEventListener('keydown', onKeydown);
    });

    if (ctx.role === 'owner') {
      // Utterance ownership in a window-global registry keyed by syncId —
      // duplicate owner instances exist (hidden render surfaces); see
      // @speakcard for the failure mode this prevents.
      const REG = window.__mdpSpeakReg || (window.__mdpSpeakReg = {});
      const key = ctx.syncId;
      const stopNow = function (answer) {
        const e = REG[key];
        if (!e) return;
        REG[key] = null;
        e.u.stop();
        if (answer && typeof e.onDone === 'function') e.onDone();
      };
      const play = function (onDone) {
        const tts = window.mdpTts;
        if (!tts || !bodyEl) { if (typeof onDone === 'function') onDone(); return; }
        stopNow(false);
        const text = (bodyEl.textContent || '').trim();
        if (!text) { if (typeof onDone === 'function') onDone(); return; }
        // The speaker as the deck wrote it; the app turns it into speak() options
        // (window.mdpTts.speakerOptions — one mapping for every module).
        const d = el.dataset;
        const spec = {
          engine: d.engine, voice: d.voice, prompt: d.prompt, extra: d.extra,
          pitch: d.pitch, intonation: d.intonation, volume: d.volume,
          lang: d.lang, rate: d.rate, fallback: d.fallback, speaker: d.speaker,
        };
        // An MDP build without speakerOptions reads it by its language only.
        const o = typeof tts.speakerOptions === 'function' ? tts.speakerOptions(spec) : { lang: spec.lang };
        // When the chosen engine could not speak, the app says what it did instead.
        o.onEngine = function (info) {
          if (!info.fallback) { ctx.setShared({ note: '' }); return; }
          console.warn('[speak] ' + info.message);
          ctx.setShared({ note: info.message || '' });
        };
        o.onProgress = function (p) {
          if (typeof p.charIndex === 'number') ctx.setShared({ prog: { ci: p.charIndex, cl: p.charLength } });
          else if (typeof p.fraction === 'number') ctx.setShared({ prog: { f: p.fraction } });
        };
        const u = tts.speak(text, o);
        const entry = { u: u, onDone: onDone, by: ctx.id };
        REG[key] = entry;
        ctx.setShared({ playing: true, prog: null });
        const done = function () {
          if (REG[key] !== entry) return; // superseded — not ours to report
          REG[key] = null;
          ctx.setShared({ playing: false, prog: null });
          if (typeof onDone === 'function') onDone();
        };
        u.done.then(done, done);
      };
      ctx.onAction(function (type) {
        if (type === 'speak') play();
        else if (type === 'stop') { stopNow(true); ctx.setShared({ playing: false, prog: null }); }
      });
      // Bus commands: `cmd:<tag> play` / `cmd:<tag> stop` (see @speakcard).
      ctx.onCommand(function (action, args, done) {
        if (action === 'play' || action === '') play(done);
        else if (action === 'stop') { stopNow(true); ctx.setShared({ playing: false, prog: null }); done(); }
        else done();
      });
      ctx.onCleanup(function () {
        if (REG[key] && REG[key].by === ctx.id) stopNow(true);
        clearHL();
      });
    } else {
      ctx.onCleanup(clearHL);
    }
    paint();
  }
}
